"use client";

import { AnimatePresence, motion } from "motion/react";
import { useId, useState } from "react";

export function TagInputTailwind() {
  const id = useId();
  const [tags, setTags] = useState(["React", "TypeScript", "Motion"]);
  const [draft, setDraft] = useState("");
  const add = () => { const t = draft.trim(); if (t && !tags.includes(t)) setTags([...tags, t]); setDraft(""); };
  return (
    <div className="w-full max-w-md space-y-2 text-zinc-100">
      <label htmlFor={id} className="text-sm font-medium">Skills</label>
      <div className="flex min-h-11 flex-wrap items-center gap-1.5 rounded-xl border border-zinc-800 bg-zinc-900 px-2 py-1.5 focus-within:border-indigo-500 focus-within:ring-4 focus-within:ring-indigo-500/25">
        <AnimatePresence initial={false} mode="popLayout">
          {tags.map((t) => (
            <motion.span layout key={t} initial={{ opacity: 0, scale: 0.6 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.6 }} className="inline-flex h-7 items-center gap-1 rounded-lg border border-indigo-500/35 bg-indigo-500/15 pl-2.5 pr-1 text-sm font-medium">
              {t}
              <button type="button" aria-label={`Remove ${t}`} onClick={() => setTags(tags.filter((x) => x !== t))} className="grid size-5 place-items-center rounded-md opacity-60 hover:opacity-100">×</button>
            </motion.span>
          ))}
        </AnimatePresence>
        <input id={id} value={draft} placeholder="Add a skill…" onChange={(e) => setDraft(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter" || e.key === ",") { e.preventDefault(); add(); } else if (e.key === "Backspace" && !draft) setTags(tags.slice(0, -1)); }} className="h-7 min-w-28 flex-1 bg-transparent px-1 text-sm outline-none placeholder:text-zinc-500" />
      </div>
    </div>
  );
}
